set local role authenticated;select set_config('request.jwt.claims','{"sub":"28000000-0000-0000-0000-000000000001","role":"authenticated","is_anonymous":true}',true);select lives_ok($$select public.submit_perfect_lie_lie('d8000000-0000-0000-0000-000000000001',current_setting('test.timeout_q')::uuid,'A convincing late lie')$$,'expired Team can still submit a lie');select ok((public.get_team_room_state('TIME20')->'perfect_lie'->'my_response'->>'timed_out')::boolean,'refresh restores timeout-specific Team state');select is(public.get_team_room_state('TIME20')->'perfect_lie'->'my_lie'->>'text','A convincing late lie','refresh restores submitted lie waiting state');select * from finish();rollback;
